program.compute:
options = read('/input/options')
result = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(options, k):
        ids = [x['id'] for x in group]
        if valid(ids):
            result = ids
            break
    if result:
        break

program.effects:
artifact = read('/output/selection')
if artifact:
    selection = artifact
    if not valid(selection):
        status('report')
else:
    selection = result
    if not selection:
        status('report')
    else:
        write('/output/selection', selection)
if selection and valid(selection):
    receipt_state = receipt('report')
    if receipt_state == 'unattempted':
        send('report', 'team', selection)
    elif receipt_state == 'unknown':
        status('report')
if exists('/tmp/cache'):
    delete('/tmp/cache')

